// ============================================
// PARSEAR COMPROBANTE + CONSTRUIR QUERY SQL
// ============================================
// Toma el texto formateado del OCR previo, extrae los campos
// relevantes (CLABE, datetime, monto, etc.) y arma el query
// dinámico para validar el pago contra loan_payments.
// ============================================

const mensaje = $input.first().json.mensaje || $input.first().json.message || '';
const identifier = $('Webhook').item.json.user_identifier;

// === 1. Detectar si el mensaje es un comprobante ===
const isReceipt = mensaje.includes('[Comprobante de transferencia recibido]');

// Si no es comprobante, devolver bandera y salir
if (!isReceipt) {
  return [{
    json: {
      ocr_data: { is_receipt: false },
      clabe: '',
      datetime: '',
      amount: 0,
      clabe_length: 0,
      caption_usuario: '',
      query: null,
      found: false,
      skip_reason: 'no_es_comprobante'
    }
  }];
}

// === 2. Helpers ===
function extractField(text, label) {
  const regex = new RegExp(`-\\s*${label}:\\s*(.+?)(?:\\n|$)`, 'i');
  const match = text.match(regex);
  if (!match) return null;
  const value = match[1].trim();
  if (/^no le[ií]do$/i.test(value) || /^no detectado$/i.test(value) || value === '') {
    return null;
  }
  return value;
}

function normaliceClabe(raw) {
  const digits = (raw || '').replace(/\D/g, '');
  if (digits.startsWith('4000') && digits.length === 22) return digits.slice(-18);
  if (digits.startsWith('400') && digits.length === 21) return digits.slice(-18);
  if (digits.length > 18) return digits.slice(-18);
  return digits;
}

// === 3. Extraer campos del texto formateado ===
const captionMatch = mensaje.match(/\[Texto del cliente\]\s*([\s\S]*?)$/);
const captionUsuario = captionMatch ? captionMatch[1].trim() : '';

const origin_bank        = extractField(mensaje, 'Banco origen');
const destination_bank   = extractField(mensaje, 'Banco destino');
const beneficiary        = extractField(mensaje, 'Beneficiario');
const amountRaw          = extractField(mensaje, 'Monto');
const datetime           = extractField(mensaje, 'Fecha') || '';
const reference          = extractField(mensaje, 'Referencia');
const tracking_key       = extractField(mensaje, 'Clave de rastreo');
const destinationAccount = extractField(mensaje, 'CLABE destino'); // si lo agregaste en old_version

// === 4. Normalizar CLABE y monto ===
// Prioridad: CLABE destino > tracking_key (fallback)
const clabeRaw = destinationAccount || tracking_key;
const clabe = normaliceClabe(clabeRaw);
const clabeLength = clabe.length;
const amount = amountRaw ? parseFloat(amountRaw.toString().replace(/[^0-9.]/g, '')) : 0;

// === 5. Validar que tenemos lo mínimo para hacer query ===
if (!datetime || datetime.trim() === '' || !clabe || clabe.trim() === '') {
  return [{
    json: {
      ocr_data: {
        is_receipt: true,
        origin_bank,
        destination_bank,
        beneficiary,
        amount,
        datetime,
        reference,
        tracking_key,
        destination_account: destinationAccount
      },
      clabe,
      datetime,
      amount,
      clabe_length: clabeLength,
      caption_usuario: captionUsuario,
      query: null,
      found: false,
      skip_reason: 'datos_insuficientes'
    }
  }];
}

// === 6. Construir query según longitud de CLABE ===
let query;

if (clabeLength === 18) {
  // CLABE completa: buscar match exacto en cualquier user
  query = `
    SELECT
      lp.id,
      up.user_id,
      CASE
        WHEN lp.paid_date > (lp.created_at AT TIME ZONE 'cst')
          THEN (lp.created_at AT TIME ZONE 'cst')
        ELSE lp.paid_date
      END AS paid_date,
      up.clabe AS bankprovider_clabe,
      ac.clabe AS payprovider_clabe
    FROM loan_payments AS lp
    LEFT JOIN user_payment_accounts AS up ON up.user_id = lp.user_id
    LEFT JOIN payprovider_customers AS ac ON lp.user_id = ac.user_id
    WHERE
      (up.clabe = '${clabe}' OR ac.clabe = '${clabe}')
      AND (lp.paid_date AT TIME ZONE 'cst') >= (TIMESTAMP '${datetime}' AT TIME ZONE 'cst')
    LIMIT 1
  `;
} else {
  // CLABE parcial: usar LIKE y restringir al user_identifier
  query = `
    SELECT
      lp.id,
      up.user_id,
      CASE
        WHEN lp.paid_date > (lp.created_at AT TIME ZONE 'cst')
          THEN (lp.created_at AT TIME ZONE 'cst')
        ELSE lp.paid_date
      END AS paid_date,
      up.clabe AS bankprovider_clabe,
      ac.clabe AS payprovider_clabe
    FROM loan_payments AS lp
    LEFT JOIN user_payment_accounts AS up ON up.user_id = lp.user_id
    LEFT JOIN payprovider_customers AS ac ON lp.user_id = ac.user_id
    WHERE
      (up.clabe LIKE '%${clabe}' OR ac.clabe LIKE '%${clabe}')
      AND (up.user_id = '${identifier}' OR ac.user_id = '${identifier}')
      AND (lp.paid_date AT TIME ZONE 'cst') >= (TIMESTAMP '${datetime}' AT TIME ZONE 'cst')
    LIMIT 1
  `;
}

// === 7. Output combinado: OCR data + query listo ===
return [{
  json: {
    // Data del comprobante (para nodos posteriores que la necesiten)
    ocr_data: {
      is_receipt: true,
      origin_bank,
      destination_bank,
      beneficiary,
      amount,
      datetime,
      reference,
      tracking_key,
      destination_account: destinationAccount
    },
    clabe,
    datetime,
    amount,
    clabe_length: clabeLength,
    caption_usuario: captionUsuario,

    // Query para el postgres node
    query
  }
}];

// ============================================
// CONSOLIDAR CONTEXTO PARA WORKFLOW `event`
// ============================================
// Toma el mensaje del comprobante (ya formateado por el OCR previo)
// + resultado de validación en BD
// y arma el context_block que `event` consumirá.
// ============================================

// === INPUTS ===
const webhook = $('Webhook').item.json;
const bdResult = $input.all(); // resultado de ejecutar_query_dinamico1

// === MENSAJE Y METADATA ===
const mensaje = webhook.mensaje || webhook.message || '';
const historial = webhook.historial || '';
const sender_name = webhook.sender_name || 'Cliente';
const total_messages = webhook.total_messages || 0;
const conversation_id = webhook.conversation_id || '';
const phone_number = webhook.phone_number || '';

// === DETECCIÓN DE COMPROBANTE Y CAPTION ===
const isReceipt = mensaje.includes('[Comprobante de transferencia recibido]');

// Extraer el texto que el usuario escribió junto con la imagen
const captionMatch = mensaje.match(/\[Texto del cliente\]\s*([\s\S]*?)$/);
const captionUsuario = captionMatch ? captionMatch[1].trim() : '';

// === DETECCIÓN DE ESCALATE POR KEYWORDS ===
// Solo evalúa el caption del cliente, no el bloque OCR
const captionLower = captionUsuario.toLowerCase();
const escalate_keywords = [
  'humano', 'asesor', 'persona real', 'hablar con alguien',
  'pésimo', 'pesimo', 'peor servicio', 'demand', 'abogado',
  'denuncia', 'fraude', 'cancelar todo', 'ya no quiero'
];
const should_escalate = escalate_keywords.some(k => captionLower.includes(k));

// === BLOQUE DE COMPROBANTE ===
// El texto del OCR ya viene formateado, lo usamos tal cual
let comprobanteBlock;
if (isReceipt) {
  // Tomamos solo la parte del comprobante (sin el caption del cliente)
  const soloComprobante = captionMatch
    ? mensaje.substring(0, captionMatch.index).trim()
    : mensaje.trim();
  comprobanteBlock = `=== COMPROBANTE OCR ===\n${soloComprobante}`;
} else {
  comprobanteBlock = `=== COMPROBANTE OCR ===\nLa imagen NO es un comprobante bancario válido.`;
}

// === VERIFICACIÓN EN BD ===
// Normalizar el resultado de Postgres
// n8n entrega: array de items, cada uno { json: { ... } }
// Si no hubo filas, suele venir [{ json: {} }] (un solo item con objeto vacío)
const bdRows = (bdResult || [])
  .map(item => item.json || item)
  .filter(row => row && row.id !== undefined && row.id !== null);

let bdBlock;
let payment_diagnosis;
let loan_info = null;

if (!isReceipt) {
  bdBlock = `=== VERIFICACIÓN BD ===\nNo se verificó en BD porque la imagen no es un comprobante.`;
  payment_diagnosis = 'no_es_comprobante';
} else if (bdRows.length === 0) {
  bdBlock = `=== VERIFICACIÓN BD ===
El pago NO se encontró en nuestra base de datos.
Posibles causas:
- La CLABE es incorrecta o no corresponde a un cliente FinDemo.
- El pago se hizo a una cuenta que no reconocemos.
- Error en el OCR al leer la CLABE o la fecha.
- La fecha del comprobante es anterior a cualquier pago registrado.`;
  payment_diagnosis = 'pago_no_encontrado';
} else {
  loan_info = bdRows[0];
  bdBlock = `=== VERIFICACIÓN BD ===
- Loan ID: ${loan_info.id}
- User ID: ${loan_info.user_id}
- Fecha de pago registrada: ${loan_info.paid_date || 'aún no pagado'}
- CLABE BankProvider: ${loan_info.bankprovider_clabe || 'no asignada'}
- CLABE PayProvider: ${loan_info.payprovider_clabe || 'no asignada'}`;

  payment_diagnosis = loan_info.paid_date
    ? 'pago_ya_registrado'
    : 'loan_encontrado_sin_pago';
}

// === CONTEXTO CONSOLIDADO ===
const context_block = `=== INFO CLIENTE ===
Nombre: ${sender_name}
Sender ID: ${webhook.sender_id || 'no disponible'}
Mensajes en este turno: ${total_messages}

${comprobanteBlock}

${bdBlock}

=== DIAGNÓSTICO ===
${payment_diagnosis}

=== TEXTO DEL CLIENTE JUNTO CON LA IMAGEN ===
${captionUsuario || '(no escribió nada, solo mandó la imagen)'}
${should_escalate ? '\nALERTA: El texto del cliente contiene señales de frustración o pedido de humano. Considera escalar.' : ''}`;

// === OUTPUT ===
return [{
  json: {
    // Campos que espera el workflow `event`
    mensaje: mensaje,
    historial: historial,
    conversation_id: conversation_id,
    total_messages: total_messages,
    phone_number: phone_number,
    route_type: 'ACTIVE_LOAN', // TODO: ajustar según lógica real
    should_escalate: should_escalate,
    context_block: context_block,

    // Metadata útil por si `event` o downstream la necesitan
    sender_id: webhook.sender_id,
    sender_name: sender_name,
    payment_diagnosis: payment_diagnosis,
    is_receipt: isReceipt,
    loan_found: loan_info !== null,
    loan_id: loan_info ? loan_info.id : null,
    user_id_bd: loan_info ? loan_info.user_id : null
  }
}];
